import domain.Account;
import domain.PasswordPolicy;
import domain.PolicyViolation;
import store.AccountStore;
import util.EmailAddresses;

import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

/** Sign-up and profile maintenance. */
public class AccountService {
    private static final Pattern USERNAME = Pattern.compile("[a-z][a-z0-9_.-]{2,31}");

    private final AccountStore accounts;
    private final PasswordHasher hasher;
    private final PasswordHistoryGuard historyGuard;
    private final PasswordPolicy policy;
    private final Clock clock;
    private final int displayNameMax;

    public AccountService(AccountStore accounts, PasswordHasher hasher, PasswordHistoryGuard historyGuard,
                          PasswordPolicy policy, Clock clock, Settings settings) {
        this.accounts = accounts;
        this.hasher = hasher;
        this.historyGuard = historyGuard;
        this.policy = policy;
        this.clock = clock;
        this.displayNameMax = settings.intValue("profile.displayNameMax", 40);
    }

    public Account signUp(String username, String email, String password) {
        List<String> problems = new ArrayList<>();
        String normalizedEmail = EmailAddresses.normalize(email);
        if (username == null || !USERNAME.matcher(username).matches()) {
            problems.add("username must be 3-32 chars: lower-case letters, digits, '_', '.', '-'");
        } else if (accounts.findByUsername(username).isPresent()) {
            throw ValidationException.of(409, "username already taken");
        }
        if (!EmailAddresses.looksValid(normalizedEmail)) {
            problems.add("email is not valid");
        } else if (accounts.emailTaken(normalizedEmail)) {
            throw ValidationException.of(409, "email already registered");
        }
        for (PolicyViolation v : policy.check(username, password)) {
            problems.add(v.message());
        }
        if (!problems.isEmpty()) {
            throw new ValidationException(422, problems);
        }
        String hash = hasher.hash(password);
        Account account = new Account(accounts.nextId(), username, normalizedEmail, username, hash, clock.instant(), false);
        accounts.save(account);
        historyGuard.remember(account.id(), hash);
        return account;
    }

    public Account rename(String accountId, String displayName) {
        Account account = accounts.findById(accountId)
                .orElseThrow(() -> ValidationException.of(404, "account not found"));
        String trimmed = displayName == null ? "" : displayName.strip();
        if (trimmed.isEmpty() || trimmed.length() > displayNameMax) {
            throw ValidationException.of(422, "display name must be 1-" + displayNameMax + " characters");
        }
        Account updated = account.withDisplayName(trimmed);
        accounts.save(updated);
        return updated;
    }

    public void disable(String accountId) {
        Account account = accounts.findById(accountId)
                .orElseThrow(() -> ValidationException.of(404, "account not found"));
        accounts.save(account.withDisabled(true));
    }
}
package app;

import api.AccountHandler;
import api.AdminHandler;
import api.Request;
import api.Response;
import api.Router;
import api.SessionHandler;
import config.Settings;
import crypto.PasswordHasher;
import domain.PasswordPolicy;
import service.AccountService;
import service.LoginService;
import service.PasswordHistoryGuard;
import service.PasswordService;
import store.AccountStore;
import store.CredentialHistoryStore;
import store.SessionStore;

import java.time.Clock;
import java.time.Duration;

/** Wires the account service together. One instance = one running server. */
public final class Application {
    private final Router router;

    private Application(Router router) {
        this.router = router;
    }

    public static Application create(Clock clock, String adminKey) {
        Settings settings = Settings.load();
        AccountStore accounts = new AccountStore();
        SessionStore sessions = new SessionStore();
        PasswordHasher hasher = new PasswordHasher();
        PasswordHistoryGuard history = new PasswordHistoryGuard(new CredentialHistoryStore(), hasher);
        PasswordPolicy policy = PasswordPolicy.DEFAULT;
        Duration ttl = Duration.ofMinutes(settings.intValue("session.ttlMinutes", 30));

        AccountService accountService = new AccountService(accounts, hasher, history, policy, clock, settings);
        PasswordService passwordService = new PasswordService(accounts, sessions, hasher, history, policy, clock);
        LoginService loginService = new LoginService(accounts, sessions, hasher, clock, ttl);

        Router router = new Router(
                new AccountHandler(accountService, passwordService, loginService),
                new SessionHandler(loginService),
                new AdminHandler(adminKey, passwordService, accountService));
        return new Application(router);
    }

    public Response handle(Request request) {
        return router.handle(request);
    }
}
package store;

import domain.Account;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public class AccountStore {
    private final Map<String, Account> byId = new LinkedHashMap<>();
    private final Map<String, String> idByUsername = new LinkedHashMap<>();
    private int sequence = 0;

    public synchronized String nextId() {
        sequence++;
        return "acc-" + sequence;
    }

    public synchronized void save(Account account) {
        Account previous = byId.put(account.id(), account);
        if (previous != null && !previous.username().equals(account.username())) {
            idByUsername.remove(previous.username());
        }
        idByUsername.put(account.username(), account.id());
    }

    public synchronized Optional<Account> findById(String id) {
        return Optional.ofNullable(byId.get(id));
    }

    public synchronized Optional<Account> findByUsername(String username) {
        String id = idByUsername.get(username);
        return id == null ? Optional.empty() : Optional.ofNullable(byId.get(id));
    }

    public synchronized boolean emailTaken(String email) {
        return byId.values().stream().anyMatch(a -> a.email().equals(email));
    }

    public synchronized List<Account> all() {
        Collection<Account> values = byId.values();
        return new ArrayList<>(values);
    }
}

